import{_ as o,l as s,o as r,c as i,v as p,p as u,x as l,d as t,i as d,S as m,b as e}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"Vega 桶与曲面风险","description":"","frontmatter":{"title":"Vega 桶与曲面风险","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vega-buckets.md","filePath":"quant/vega-buckets.md","lastUpdated":1789023840000}'),g={name:"quant/vega-buckets.md"};function h(A,a,E,b,c,B){const n=s("Mermaid");return r(),i("div",null,[a[1]||(a[1]=p('<h1 id="vega-桶与曲面风险" tabindex="-1">Vega 桶与曲面风险 <a class="header-anchor" href="#vega-桶与曲面风险" aria-label="Permalink to &quot;Vega 桶与曲面风险&quot;">​</a></h1><div class="epigraph"><p>一个总 Vega 把微笑的水平、斜率和弯曲捆在一起；桶风险是按到期与 Delta 把曲面节点当成可 bump 的市场数据。</p><footer>—— 对照 Derman 对波动率曲面风险的论述；桶划分见期权风险报告惯例</footer></div><p><a href="/quant/pathwise-likelihood-ratio">上一课</a>给出如何估 \\(\\partial V/\\partial\\theta\\)。本课的 \\(\\theta\\) 不再是一个 \\(\\sigma\\)，而是<strong>曲面上的一排节点</strong>。主干 <a href="/quant/vol-surface">隐波曲面</a> 与 <a href="/quant/greeks-hedge">Delta 对冲</a> 已写水平和局部对冲。缺口是报告：结构产品的风险要按桶加总，才能拿去对冲香草。后课曲面动态再把桶随时间怎么一起动写进去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BSM Vega 是价值对常数 \\(\\sigma\\) 的导。真实市场动的是一张 \\((T,K)\\) 或 \\((T,\\Delta)\\) 网格。总 Vega 可能接近 0，同时短到期数字桶和长到期斜度桶都很大——autocallable、cliquet 典型如此。问题是定义 bump：按原始报价惯例（FX 的 ATM/RR/BF，股权的按 \\(K\\) 或按 \\(\\Delta\\)）去 bump，再通过无套利插值传到定价引擎，而不是在引擎内部的参数（Heston \\(\\kappa,\\nu\\)）上 bump 再假装那是市场 Vega。</p><p>桶边界是设定：到期 1M/3M/1Y、Delta 25/10 等。边界一改，同一组合的「最大桶」会换位置。报告必须固定网格，校准与 AAD 的输入应对齐这张网格。</p><h3 id="模型-vega-不是市场-vega" tabindex="-1">模型 Vega 不是市场 Vega <a class="header-anchor" href="#模型-vega-不是市场-vega" aria-label="Permalink to &quot;模型 Vega 不是市场 Vega&quot;">​</a></h3><p>在 <a href="/quant/heston">Heston</a> 里对 \\(\\nu\\) 求导，是模型参数敏感度，用于校准与模型风险。市场 Vega 是对可交易香草价格（或隐波节点）的导数。对冲只能买后者。把 Heston Vega 拿去下香草单，单位都对不上。AAD 若以曲面节点为输入，输出的才是市场桶；若以模型参数为输入，输出的是另一张表，两张都要，不要合并成一行「Vega」。</p><p><span class="marginnote">平行 bump 整张曲面，近似「水平」风险，对偏斜产品会漏掉主风险。至少要水平、倾斜、弯曲三个情景，或完整桶矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选择与报价一致的节点；用 <a href="/quant/arb-free-iv">无套利插值</a> 填充。每个节点 bump 1 个波动点（或按 RR/BF 的惯例 bump），重估或用 AAD。加总到内部限额：按到期、按货币、按标的。对冲：用该桶附近的香草或方差互换去减最大项，残差进次主桶。数字与障碍在对应 \\(K\\) 的短到期桶上会出尖峰，对冲应用价差而不是 ATM。</p><p>利率与股权混合结构要同时报 IR 桶与 EQ 桶，不要把一切折成「股权总 Vega」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定价映射 \\(\\mathrm{surface}\\mapsto V\\) 的 Jacobian 就是桶风险。插值核决定 bump 如何传染邻居：局部插值让桶更「对角」，全局参数化（SVI 全期限一个参数）会让一次 bump 污染整张曲面，报告看起来平滑、对冲却对不上可交易工具。这就是为什么桶应定义在报价节点上，而不是定义在内部参数上。</p>',14)),(r(),u(m,null,{default:l(()=>[d(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Quote%5B%22%E6%8A%A5%E4%BB%B7%E8%8A%82%E7%82%B9%20ATM%20RR%20%E6%88%96%20K%22%5D%20--%3E%20Interp%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E6%8F%92%E5%80%BC%22%5D%0A%20%20Interp%20--%3E%20Eng%5B%22%E5%AE%9A%E4%BB%B7%E5%BC%95%E6%93%8E%22%5D%0A%20%20Eng%20--%3E%20Buck%5B%22AAD%20%E6%88%96%20bump%20%E7%9A%84%E6%A1%B6%20Jacobian%22%5D%0A%20%20Buck%20--%3E%20Hdg%5B%22%E7%94%A8%E5%8F%AF%E4%BA%A4%E6%98%93%E9%A6%99%E8%8D%89%E5%87%8F%E4%B8%BB%E6%A1%B6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"边界",tabindex:"-1"},[t("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[3]||(a[3]=e("p",null,"流动性：10 Delta 翼部 bump 1 点可能比 ATM 1 点贵得多，名义风险与可对冲风险不同。跳空使短到期桶的已实现与 bump 情景不一致。XVA 的曲面风险还含对手方与自身曲线，后课再接。不要用历史 PCA 的第一主成分去替代当日桶——那是下一课动态，不是今日对冲清单。",-1)),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"总 Vega 不够；风险是曲面上按报价惯例定义的桶。"),e("li",null,"市场桶与模型参数敏感度必须分表。"),e("li",null,"插值核会污染邻居，桶应钉在可交易节点上。"),e("li",null,"出处：曲面作为市场数据见 Derman 等关于波动率的论述；报告网格是市场惯例。")],-1))])}const D=o(g,[["render",h]]);export{V as __pageData,D as default};
